// Bring in the Verus prelude to get `#[requires]`, `#[ensures]`, and `forall`
use verus::prelude::*;

/// Creates a row of length `n` where element i is equal to i.
#[requires(true)]
#[ensures(|result: Vec<u8>| 
    // the length is n
    result.len() == n as usize
    // and for every index i < n, result[i] == i
    && forall(|i: usize| i < n as usize ==> result[i] == i as u8)
)]
fn create_row(n: u8) -> Vec<u8> {
    // (0..n) is an iterator yielding 0, 1, …, n-1; collect into a Vec<u8>
    (0..n).collect()
}

/// Creates a 2D grid containing exactly one row, as specified by `create_row`.
#[requires(true)]
#[ensures(|res: Vec<Vec<u8>>|
    // exactly one row in the outer vector
    res.len() == 1
    // that one row has length n
    && res[0].len() == n as usize
    // and each element of that row satisfies row[i] == i
    && forall(|i: usize| i < n as usize ==> res[0][i] == i as u8)
)]
fn indices(n: u8) -> Vec<Vec<u8>> {
    vec![create_row(n)]
}

